{
  "title": "Jumia Scraper",
  "description": "Get detailed product listing informations from Jumia search results, merchant pages, categories or individual listing pages.",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "startUrls": {
      "sectionCaption": "Scrape by URL 🎯",
      "title": "Enter Jumia search, category, merchant or individual listing URLs to scrape",
      "type": "array",
      "description": "Paste one or more Jumia Search, Category, merchant or individual listing page URLs to scrape.",
      "editor": "stringList",
      "prefill": [
        "https://www.jumia.com.ng/mens-baseball-caps/?price=1911-3000#catalog-listing"
      ]
    },
    "queries": {
      "sectionCaption": "Scrape by Query 🎯",
      "title": "Enter Jumia Search queries to scrape",
      "type": "array",
      "description": "Paste one or more Jumia search queries to scrape.",
      "editor": "stringList"
    },
    "limit": {
      "sectionCaption": "Max Limit 💯",
      "title": "Maximum listings to collect",
      "type": "integer",
      "description": "Stop the run after this number of listings has been saved per input.",
      "default": 50000,
      "minimum": 10
    },
    "proxyConfiguration": {
      "sectionCaption": "Connection settings ⚙️",
      "title": "Proxy configuration",
      "type": "object",
      "description": "The default Apify Residential proxy keeps the scraper reliable.",
      "editor": "proxy",
      "default": {
        "useApifyProxy": true,
        "apifyProxyGroups": [
          "RESIDENTIAL"
        ]
      }
    }
  }
}
